# 这里func是传递的函数
def liner(func):
    # 定义嵌套函数
    def inner():
        print('----------')
        # 调用传递的函数
        func()
        print('----------')

    # 返回嵌套函数inner
    return inner

# 这里func是传递的函数
def liner(func):
    # 定义嵌套函数
    def inner():
        print('----------')
        # 调用传递的函数
        func()
        print('----------')

    # 返回嵌套函数inner
    return inner

# 方法 1
def normal():
    print('normal')


decorated = liner(normal)
decorated()

# 方法 2
@liner
def decorated():
    print('decorated')


decorated()
